"""A Design-board artboard: party avatars (initials) with the character's name above or below."""
import os, sys
OUT = sys.argv[1]
PARTY = [
    {"name": "Garra Windmane", "short": "GW", "portrait": "male-tauren", "color": "#aad372", "has": True, "counts": [4, 7, 1, 0, 3, 2]},
    {"name": "Brakkastonex Thunderhoofs", "short": "BT", "portrait": "female-orc", "color": "#c69b6d", "has": True, "counts": [7, 10, 2, 1, 5, 6]},
    {"name": "Mirandel Ashvale", "short": "MA", "portrait": "female-scourge", "color": "#ffffff", "has": False, "counts": None},
    {"name": "Olen Rusk", "short": "OR", "portrait": "male-troll", "color": "#3fc7eb", "has": True, "counts": None},
]
OBJECTIVES = [("Plainstrider Beak", 7), ("Zhevra Hoof", 10), ("Kolkar Leader slain", 2), ("Barak's Head", 1), ("Centaur Bracers", 5), ("Raptor Head", 6)]
MINE = [3, 10, 0, 0, 5, 1]
PORTRAITS = {'male-tauren': 'data:image/png;base64,', 'female-orc': 'data:image/png;base64,', 'male-troll': 'data:image/png;base64,', 'female-scourge': 'data:image/png;base64,'}
GOLD, TAN, GREEN, GREY = "#ffd100", "#c8b48a", "#7ce07c", "#8a8578"

def avatar(m, size, dark=True, badge=False):
    image = PORTRAITS[m["portrait"]]
    filt = "" if m["has"] else "filter:grayscale(1) brightness(.75);"
    ring = "#c9a227" if m["has"] else "#6b6450"
    face = (f'<span style="position:relative;display:inline-block;width:{size}px;height:{size}px;border-radius:50%;'
            f'background:#000 url({image}) center/112% no-repeat;{filt}box-shadow:0 0 0 2px {ring},0 0 0 3px #000,inset 0 0 4px #000"></span>')
    if not badge:
        return face
    b = max(13, round(size * 0.5))
    color = m["color"] if m["has"] else GREY
    tag = (f'<span style="position:absolute;left:{-size * 0.18:.0f}px;bottom:{-size * 0.14:.0f}px;width:{b}px;height:{b}px;border-radius:50%;'
           f'background:#16120a;box-shadow:0 0 0 1.5px #c9a227,0 0 0 2.5px #000;display:flex;align-items:center;justify-content:center;'
           f'font:700 {b * 0.46:.0f}px/1 \'Source Sans 3\';color:{color}">{m["short"]}</span>')
    return f'<span style="position:relative;display:inline-block">{face}{tag}</span>'

def initials(m, width, light):
    color = m["color"] if light else ("#3a2400" if m["color"] == "#ffffff" else "#2b1d0e")
    if not m["has"]:
        color = GREY if light else "#8a7a5a"
    return f'<span title="{m["name"]}" style="display:block;width:{width}px;text-align:center;font:700 11px/1.1 \'Source Sans 3\';color:{color}">{m["short"]}</span>'

def old_avatar(m, size, dark=True):
    if m["has"]:
        ring = f"border:2px solid {m['color']};color:{m['color']}"
    else:
        ring = f"border:2px dashed {GREY};color:{GREY}"
    return (f'<span style="display:inline-flex;align-items:center;justify-content:center;width:{size}px;height:{size}px;border-radius:50%;'
            f'background:#16120a;{ring};box-sizing:border-box;font:700 {size * 0.4:.0f}px/1 \'Source Sans 3\';box-shadow:0 0 0 1px #000">{m["short"]}</span>')

def label(m, width, light, part=None):
    color = m["color"] if light else ("#3a2400" if m["color"] == "#ffffff" else "#2b1d0e")
    if not m["has"]:
        color = GREY if light else "#8a7a5a"
    first, last = m["name"].split(" ", 1)
    words = [first, last] if part is None else [first if part == "first" else last]
    return "".join(f'<span style="display:block;width:{width}px;text-align:center;font:600 10.5px/1.15 \'Source Sans 3\';color:{color};'
                   f'white-space:nowrap;overflow:hidden;text-overflow:ellipsis">{word}</span>' for word in words)

def head(m, width, size, place, light):
    if place == "badge":
        parts = [avatar(m, size, badge=True)]
    else:
        parts = [initials(m, width, light), avatar(m, size)] if place == "above" else [avatar(m, size), initials(m, width, light)]
    return f'<div style="display:flex;flex-direction:column;align-items:center;gap:4px;width:{width}px" title="{m['name']}">{"".join(parts)}</div>'

def cell(m, i, light):
    req = OBJECTIVES[i][1]
    if not m["has"]:
        return f'<span style="color:{GREY if light else "#9a8b6a"}">–</span>'
    if m["counts"] is None:
        return f'<span style="color:{GREY if light else "#9a8b6a"}">?</span>'
    c = m["counts"][i]
    if c >= req:
        return f'<span style="color:{GREEN if light else "#2f8a2f"}">✓</span>'
    return str(c)

def tracker(place):
    col = 40
    heads = "".join(head(m, col, 24, place, True) for m in PARTY)
    rows = ""
    for i, (name, req) in enumerate(OBJECTIVES):
        cells = "".join(f'<span style="width:{col}px;text-align:center">{cell(m, i, True)}</span>' for m in PARTY)
        rows += (f'<div style="display:flex;font-size:12px;line-height:17px"><span style="flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">{name}</span>'
                 f'<span style="width:36px;text-align:right;margin-right:4px">{MINE[i]}/{req}</span>{cells}</div>')
    title = (f'<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px"><span style="width:14px;height:14px;border-radius:50%;background:radial-gradient(circle at 38% 32%,#ffe58a,#e3b23c 55%,#9c6a12);border:1px solid #5a3a08"></span>'
             f'<span style="color:#fff">[14] Centaur and Beast</span></div>')
    header = f'<div style="display:flex;align-items:flex-end;margin:2px 0 3px"><span style="flex:1"></span><span style="width:36px;text-align:right;margin-right:4px;font-size:10.5px;color:{TAN}">you</span>{heads}</div>'
    body = title + (header + rows if place != "below-after" else rows)
    return (f'<div style="width:330px;background:rgba(0,0,0,.55);border-radius:4px;padding:8px 8px 10px;font:13px/1.35 \'Source Sans 3\';color:#e8e2d0">'
            f'<div style="display:flex;justify-content:space-between;border-bottom:1px solid #6b5a2e;padding-bottom:3px;margin-bottom:6px">'
            f'<span style="font:400 13px Marcellus,Georgia;color:{GOLD}">Quests</span><span style="color:{TAN}">The Barrens</span></div>{body}</div>')

def page(place):
    col = 50
    heads = "".join(head(m, col, 32, place, False) for m in PARTY)
    rows = ""
    for i, (name, req) in enumerate(OBJECTIVES):
        cells = "".join(f'<span style="width:{col}px;text-align:center">{cell(m, i, False)}</span>' for m in PARTY)
        rows += (f'<div style="display:flex;font-size:12.5px;line-height:19px;border-top:1px solid rgba(90,60,20,.15)"><span style="flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">{name}</span>'
                 f'<span style="width:38px;text-align:right;margin-right:6px">{MINE[i]}/{req}</span>{cells}</div>')
    header = f'<div style="display:flex;align-items:flex-end;margin-bottom:4px"><span style="flex:1"></span><span style="width:38px;text-align:right;margin-right:6px;font-weight:600;font-size:12px">You</span>{heads}</div>'
    legend = '<div style="font-size:11px;color:#6b5636;margin-top:6px">– does not have it · ? not shared (no addon) · ✓ done</div>'
    return (f'<div style="width:410px;background:linear-gradient(#e9d7ad,#d9c391);border-radius:3px;padding:12px 14px;font:13px/1.4 \'Source Sans 3\';color:#2b1d0e;box-shadow:inset 0 0 18px rgba(80,50,10,.35)">'
            f'<div style="font:400 17px Marcellus,Georgia;color:#3a2400;margin-bottom:8px">Party</div>{header}{rows}{legend}</div>')

def column(title, text, pictures, recommended=False):
    flag = ' <span style="font:600 10px/1 \'Source Sans 3\';color:#1c1912;background:#ffd100;border-radius:3px;padding:2px 5px;margin-left:6px">Recommended</span>' if recommended else ""
    return (f'<div style="display:flex;flex-direction:column;gap:12px;width:430px"><div style="font:400 18px/1.2 Marcellus,Georgia,serif;color:#ffd100">{title}{flag}</div>'
            f'<div style="font-size:12px;line-height:1.45;color:#d8cfa8;min-height:36px">{text}</div>{pictures}</div>')

cols = (column("A. Initials below the portrait", "The character's portrait heads the column, its initials under it, right over the counts. Hover shows the full name.",
               tracker("below") + page("below"))
        + column("B. Initials above the portrait", "The initials on top, the portrait right over its column of counts.",
                 tracker("above") + page("above"))
        + column("C. Initials in a badge on the portrait", "As the game's unit frame shows the level: the initials in a small round badge at the portrait's corner. The shortest header, nothing to line up.",
                 tracker("badge") + page("badge"), True))
width, height = 30 * 2 + 3 * 430 + 2 * 40, 940
board = f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Party avatars with names</title>
<script src="./support.js"></script>
</head>
<body>
<x-dc>
<helmet>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Marcellus&amp;family=Source+Sans+3:wght@400;600;700&amp;display=swap">
<style>body{{margin:0}}</style>
</helmet>
<div style="width:{width}px;height:{height}px;box-sizing:border-box;padding:30px;display:flex;flex-direction:column;gap:18px;background:#2b3427;font-family:'Source Sans 3',system-ui,sans-serif;color:#e6e6e6">
<div style="font-size:13px;color:#d8cfa8;line-height:1.5">Each member's portrait, as the game's unit frames show it (in game their own face; here the game's race portraits stand in), with the initials of their first and last name. Mirandel Ashvale does not have the quest (greyed), Olen Rusk does not share progress. Hovering a portrait gives the full name.</div>
<div style="display:flex;gap:40px;align-items:flex-start">{cols}</div>
</div>
</x-dc>
<script type="text/x-dc" data-dc-script data-props='{{"$preview":{{"width":{width},"height":{height}}}}}'>
class Component extends DCLogic {{
renderVals() {{
return {{}};
}}
}}
</script>
</body>
</html>
'''
open(os.path.join(OUT, "PartyNames.dc.html"), "w", encoding="utf-8").write(board)
print("ok", width, height)
